DELETE FROM "airtable"."meeting_attendance" as d WHERE EXISTS (SELECT 1 FROM "airtable_staging"."meeting_attendance" as s WHERE d."id" = s."id")
INSERT INTO "airtable"."meeting_attendance"("id", "created_time", "_dlt_load_id", "_dlt_id", "fields__date", "fields__email", "fields__feedback", "fields__name", "fields__notes")                  SELECT "id", "created_time", "_dlt_load_id", "_dlt_id", "fields__date", "fields__email", "fields__feedback", "fields__name", "fields__notes"                     FROM (                         SELECT ROW_NUMBER() OVER (partition BY "id" ORDER BY (SELECT NULL)) AS _dlt_dedup_rn, "id", "created_time", "_dlt_load_id", "_dlt_id", "fields__date", "fields__email", "fields__feedback", "fields__name", "fields__notes"                         FROM "airtable_staging"."meeting_attendance"                     ) AS _dlt_dedup_numbered WHERE _dlt_dedup_rn = 1 AND (1 = 1)          